using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;

// --- Tool Definitions ---

/// <summary>Tools for web searching and note-taking used by the research agent.</summary>
static class ResearchTools
{
    private static readonly List<string> _notes = [];
    private static readonly HttpClient _http = new();

    [Description("Search the web for information on a given query. Returns a list of search result snippets.")]
    public static async Task<string> WebSearch(string query)
    {
        // Uses DuckDuckGo Instant Answer API as a free, no-key search source
        var encoded = Uri.EscapeDataString(query);
        var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

        try
        {
            var response = await _http.GetFromJsonAsync<JsonElement>(url);
            var results = new List<string>();

            // Extract abstract
            var abstractText = response.GetProperty("AbstractText").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
                results.Add($"[Summary] {abstractText}");

            // Extract related topics
            if (response.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text))
                        results.Add($"[Related] {text.GetString()}");
                }
            }

            return results.Count > 0
                ? string.Join("\n\n", results)
                : "No results found. Try rephrasing your query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    [Description("Save a research note. Use this to record key findings as you research.")]
    public static string TakeNote(string note)
    {
        _notes.Add(note);
        return $"Note saved ({_notes.Count} total notes).";
    }

    [Description("Retrieve all saved research notes.")]
    public static string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
    }
}

// --- Main Program ---

Console.WriteLine("=== AI Research Agent ===");
Console.WriteLine();

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY");
if (string.IsNullOrEmpty(apiKey))
{
    Console.WriteLine("Please set the OPENAI_API_KEY environment variable.");
    Console.WriteLine("Usage: OPENAI_API_KEY=<key> dotnet run");
    return;
}

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

IChatClient client = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(ResearchTools.WebSearch),
        AIFunctionFactory.Create(ResearchTools.TakeNote),
        AIFunctionFactory.Create(ResearchTools.GetNotes),
    ]
};

Console.Write("Enter a research topic: ");
var topic = Console.ReadLine();

if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine();
Console.WriteLine($"Researching: {topic}");
Console.WriteLine(new string('-', 40));

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to research a topic thoroughly using web search,
        take notes on important findings, then provide a comprehensive summary.

        Process:
        1. Search for the topic using multiple queries to gather diverse information.
        2. Take notes on key findings as you go.
        3. After gathering enough information, review your notes and provide a final summary.

        Always cite your sources and organize the summary with clear sections.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
};

var response = await client.GetResponseAsync(messages, chatOptions);
Console.WriteLine();
Console.WriteLine(response.Text);

